                    result["conflicts"].append({**check, "conflict": "DECLARED_LEDGER_CANNOT_PAY_COST"})
                    check["status"] = "CONFLICT"
                    result["deployment_checks"].append(check)
                else:
                    check["status"] = "PASS_WITH_CONDITIONS"
                    result["deployment_checks"].append(check)
